fn binary_search(a: &[i32], key: i32) -> usize {
    let mut low = 0;
    let mut high = a.len();
    while low < high {
        let mid = low + (high - low) / 2;
        if a[mid] < key {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    low
}

